// General revision-09 public-law episode and arbitrary-epoch BCRH batch ABIs.
// Included once by bpcr_backend.cpp; all execution is native and batch-only.
namespace bpcr_general {
constexpr int G_NULL=255,G_MAX_AGENTS=8,G_TOKENS=4,G_POST=6,G_AGENT_W=38,G_ZONE_W=15,G_GLOBAL_W=4;
struct GAgentIn{std::int32_t rank,opaque_rank,fast,radio,node,edge_from,edge_to,edge_remaining,destination_node,token,token_state,acquisition_elapsed,energy_fifths;};
struct GEpisodeInput{std::uint64_t magic;std::int32_t abi,failed_zone,active_count;GAgentIn agents[8];std::int32_t demand1[12],demand2[12],blocked1[12],blocked2[12];std::int32_t post_commands[24];std::int32_t post_presentation[48];};
struct GDecisionTrace{std::int32_t active_count,epoch,command[4],token_state[4],token_elapsed[4],legality[32],eta[32],margin_fifths[32];double agent_rows[304],zone_rows[30],globals[4];};
struct GEpisodeOutput{std::int32_t status,failed_rank,integrated_ticks,prehistory_decisions,post_decisions,safety_violation,exclusivity_violation,event_count;std::int64_t fail_delivered,fail_demand,total_delivered,total_demand,intact_delivered,intact_demand;std::int32_t prehistory_commands[24];GDecisionTrace traces[6];};
struct GBcrhInput{std::uint64_t magic;std::int32_t abi,epoch,failed_zone,active_count;GAgentIn agents[8];std::int32_t clearance[4];std::int64_t accrued_fail_delivered,accrued_fail_demand,accrued_total_delivered,accrued_total_demand;std::int32_t demand1,demand2,blocked1,blocked2;};
struct GBcrhCandidateRecord{std::int32_t command[4],floor_num,floor_den,releases;std::uint64_t objective_limbs[4];std::int32_t checker_floor_num,checker_floor_den,checker_releases;std::uint64_t checker_objective_limbs[4];std::int32_t exact_match;};
struct GBcrhOutput{std::int32_t status,candidate_count,scorer_command[4],checker_command[4],scorer_checker_equal,independent_enumerator_equal,post60_reduced,floor_num,floor_den,releases,event_records,reward_records;std::uint64_t objective_limbs[4],checker_objective_limbs[4],candidate_digest,checker_digest;GBcrhCandidateRecord records[1961];};
struct GSensitivityInput{GBcrhInput current;std::int32_t demand1[3],demand2[3],blocked1[3],blocked2[3];};
struct GSensitivityOutput{std::int32_t status,candidate_count,min_c60,max_c60,sensitive,min_command[4],max_command[4];};
struct GInteractiveOutput{std::int32_t status,terminal,epoch,failed_rank,integrated_ticks,safety_violation,exclusivity_violation,event_count;std::int64_t fail_delivered,fail_demand,total_delivered,total_demand,intact_delivered,intact_demand;std::int32_t prehistory_commands[24];GDecisionTrace applied_decision,next_observation;};
struct GClearanceInput{std::uint64_t magic;std::int32_t abi,holder_state;};
struct GClearanceOutput{std::int32_t status,clearance_after_relinquish;};
struct GPrehistoryOutput{std::int32_t status,command[4];};

struct GA{int rank,opaque,fast,radio,node,edge_from,edge_to,edge_remaining,dest,token,state,elapsed,energy;};
struct GS{std::vector<GA>a;std::array<int,4>clear{};std::array<std::int64_t,2>zd{},za{};int failed_zone=0,post_time=-120;std::int64_t af=0,df=0,at=0,dt=0,ai=0,di=0;};
struct GC{std::array<int,4>o{};bool operator==(const GC&x)const{return o==x.o;}};
struct GBig{std::array<std::uint64_t,4>x{};static GBig from(std::uint64_t v){GBig z;z.x[0]=v;return z;}void add(const GBig&o){unsigned char c=0;for(int i=0;i<4;++i)c=_addcarry_u64(c,x[i],o.x[i],&x[i]);if(c)throw std::overflow_error("gbig add");}GBig mul(std::uint64_t v)const{GBig z;std::uint64_t carry=0;for(int i=0;i<4;++i){std::uint64_t hi=0,lo=_umul128(x[i],v,&hi),sum=0;unsigned char c=_addcarry_u64(0,lo,carry,&sum);z.x[i]=sum;if(i==3&&(hi||c))throw std::overflow_error("gbig mul");carry=hi+c;}return z;}friend bool operator==(const GBig&a,const GBig&b){return a.x==b.x;}friend bool operator!=(const GBig&a,const GBig&b){return!(a==b);}friend bool operator<(const GBig&a,const GBig&b){for(int i=3;i>=0;--i)if(a.x[i]!=b.x[i])return a.x[i]<b.x[i];return false;}friend bool operator>(const GBig&a,const GBig&b){return b<a;}};

int gedge_time(bool fast,int from,int to){int t=0;if((from==0&&to==1)||(from==1&&to==0)||(from==1&&to==2)||(from==2&&to==1)||(from==3&&to==4)||(from==4&&to==3))t=20;else if((from==0&&to==3)||(from==3&&to==0))t=30;else if((from==1&&to==3)||(from==3&&to==1))t=40;else throw std::logic_error("nonedge");return fast?std::max(5,5*((3*t+19)/20)):t;}
int gnext(int from,int to){if(from==to)return to;static const int n[5][5]={{0,1,1,3,3},{0,1,2,3,3},{1,1,2,1,1},{0,1,1,3,4},{3,3,3,3,4}};return n[from][to];}
int gtoken_node(int t){return t<2?(t?1:2):(t==2?4:3);}int gacq(int t){return(t==0||t==2)?6:4;}
int gfind(const GS&s,int rank){for(std::size_t i=0;i<s.a.size();++i)if(s.a[i].rank==rank)return(int)i;return-1;}
bool genroute(const GA&a){return a.edge_remaining>0||a.node!=a.dest;}
void gstart_route(GA&a,int dest){a.dest=dest;if(a.node==dest){a.edge_from=a.edge_to=-1;a.edge_remaining=0;return;}int next=gnext(a.node,dest);a.edge_from=a.node;a.edge_to=next;a.edge_remaining=gedge_time(a.fast,a.node,next);}
void gcontinue(GA&a){if(a.node==a.dest){a.edge_from=a.edge_to=-1;a.edge_remaining=0;return;}int next=gnext(a.node,a.dest);a.edge_from=a.node;a.edge_to=next;a.edge_remaining=gedge_time(a.fast,a.node,next);}
int gtravel_remaining(GA a,int dest){int total=a.edge_remaining;if(a.edge_remaining){a.node=a.edge_to;}while(a.node!=dest){int next=gnext(a.node,dest);total+=gedge_time(a.fast,a.node,next);a.node=next;}return total;}
std::pair<int,int> gcontingency(const GS&s,const GA&source,int token){if(genroute(source))return{0,0};GA a=source;int target=gtoken_node(token);bool retain=a.token==token&&a.node==target;int min_energy=a.energy;if(!retain){gstart_route(a,target);a.token=token;a.state=1;a.elapsed=0;}int local_clear=retain?0:s.clear[token];if(!retain)for(const auto&other:s.a)if(other.rank!=a.rank&&other.token==token&&other.state>0)local_clear=std::max(local_clear,1);int eta;if(retain)eta=a.state==2?0:gacq(token)-a.elapsed;else{int arrival=gtravel_remaining(source,target),hazard=(token==(s.failed_zone==1?0:2)&&s.post_time>=0)?std::max(0,20-s.post_time):0;eta=std::max({arrival,local_clear,hazard})+gacq(token);}
    for(int second=0;second<400;++second){if(second>0&&second%20==0&&!genroute(a)&&a.node!=0){a.token=-1;a.state=0;a.elapsed=0;gstart_route(a,0);}if(second>=20&&a.node==0&&!genroute(a))break;if(a.edge_remaining){a.energy-=a.fast?6:5;if(--a.edge_remaining==0){a.node=a.edge_to;gcontinue(a);}}else if(a.node==target&&local_clear==0&&!(token==(s.failed_zone==1?0:2)&&s.post_time+second>=0&&s.post_time+second<20)){if(a.state==2)a.energy-=(token==0||token==2)?2:1;else if(++a.elapsed==gacq(token))a.state=2;}min_energy=std::min(min_energy,a.energy);if(local_clear)local_clear--;}
    return{eta,min_energy-100};}
int gtoken_state(const GS&s,int token,int&elapsed,int&rank){int state=0;elapsed=0;rank=G_NULL;for(const auto&a:s.a)if(a.token==token){if(rank!=G_NULL)throw std::logic_error("exclusive");rank=a.rank;elapsed=a.elapsed;state=a.state;}return state;}
bool gfixed_token(const GS&s,int token,int&rank){for(const auto&a:s.a)if(a.token==token&&genroute(a)){rank=a.rank;return true;}rank=G_NULL;return false;}
void genum_rec(const GS&s,int token,std::array<bool,9>&used,GC&c,std::vector<GC>&out,bool prehistory){if(token==4){out.push_back(c);return;}int fixed;if(gfixed_token(s,token,fixed)){c.o[token]=fixed;genum_rec(s,token+1,used,c,out,prehistory);return;}if(prehistory&&((token==1&&false)||(token==3&&false))){}
    c.o[token]=G_NULL;genum_rec(s,token+1,used,c,out,prehistory);for(const auto&a:s.a)if(!used[a.rank]&&!genroute(a)){auto lm=gcontingency(s,a,token);if(lm.second>=0){used[a.rank]=true;c.o[token]=a.rank;genum_rec(s,token+1,used,c,out,prehistory);used[a.rank]=false;}}}
std::vector<GC> genum(const GS&s,bool prehistory=false){std::vector<GC>out;GC c;c.o.fill(G_NULL);std::array<bool,9>used{};for(int token=0;token<4;++token){int fixed;if(gfixed_token(s,token,fixed))used[fixed]=true;}genum_rec(s,0,used,c,out,prehistory);return out;}
bool gcommand_legal(const GS&s,const GC&c);
std::vector<GC> genum_checker(const GS&s){std::vector<GC>out;int radix=(int)s.a.size()+1,end=radix*radix*radix*radix;for(int code=0;code<end;++code){int x=code;GC c;for(int t=0;t<4;++t){int d=x%radix;x/=radix;c.o[t]=d? s.a[d-1].rank:G_NULL;}if(gcommand_legal(s,c))out.push_back(c);}return out;}
int gcommand_error(const GS&s,const GC&c){std::array<bool,9>used{};for(int t=0;t<4;++t){int fixed;if(gfixed_token(s,t,fixed)&&c.o[t]!=fixed)return 10+t;int r=c.o[t];if(r==G_NULL)continue;if(r<1||r>8||used[r])return 20+t;used[r]=true;int i=gfind(s,r);if(i<0)return 30+t;if(genroute(s.a[i])&&s.a[i].token!=t)return 35+t;if(!genroute(s.a[i])&&gcontingency(s,s.a[i],t).second<0)return 40+t;}return 0;}
bool gcommand_legal(const GS&s,const GC&c){return gcommand_error(s,c)==0;}
std::tuple<int,int,int> gcriterion(const GS&s,const GC&c,int token,bool exec){int r=c.o[token];if(r==G_NULL)return{1000000,1000000,1000000};const GA&a=s.a[gfind(s,r)];auto em=gcontingency(s,a,token);return exec?std::tuple(em.first,-a.radio,a.opaque):std::tuple(-a.radio,em.first,a.opaque);}
std::array<int,4> gserial(const GS&s,const GC&c){std::array<int,4>out{};for(int t=0;t<4;++t)out[t]=c.o[t]==G_NULL?1000000:s.a[gfind(s,c.o[t])].opaque;return out;}
GC gprehistory(const GS&s,int h1,int h2){auto all=genum(s,true);std::vector<GC>valid;for(const auto&c:all){bool ok=true;for(const auto&a:s.a)if(a.state==2&&(a.token==0||a.token==2)){if(gcontingency(s,a,a.token).second>=0&&c.o[a.token]!=a.rank)ok=false;}int fixed1,fixed3;bool f1=gfixed_token(s,1,fixed1),f3=gfixed_token(s,3,fixed3);if((!h1&&c.o[1]!=G_NULL&&!f1)||(!h2&&c.o[3]!=G_NULL&&!f3))ok=false;if(ok)valid.push_back(c);}if(valid.empty())throw std::logic_error("prehistory empty");auto key=[&](const GC&c){int ex=(c.o[0]!=G_NULL)+(c.o[2]!=G_NULL),rel=h1*(c.o[1]!=G_NULL)+h2*(c.o[3]!=G_NULL);return std::tuple(-ex,gcriterion(s,c,0,true),gcriterion(s,c,2,true),c.o[1]!=G_NULL&&!h1,c.o[3]!=G_NULL&&!h2,-rel,gcriterion(s,c,1,false),gcriterion(s,c,3,false),gserial(s,c));};return*std::min_element(valid.begin(),valid.end(),[&](const GC&a,const GC&b){return key(a)<key(b);});}
int gapply(GS&s,const GC&c){int error=gcommand_error(s,c);if(error)return error;for(auto&a:s.a){if(genroute(a))continue;int assigned=-1;for(int t=0;t<4;++t)if(c.o[t]==a.rank)assigned=t;if(a.state>0&&a.token>=0&&assigned!=a.token)s.clear[a.token]=std::max(s.clear[a.token],1);if(assigned!=a.token){a.state=assigned<0?0:1;a.elapsed=0;}a.token=assigned;if(assigned<0)gstart_route(a,0);else gstart_route(a,gtoken_node(assigned));}return 0;}
std::array<int,2> gdelivery(const GS&s,int q1,int q2,int h1,int h2){std::array<int,2>d{};for(int z=0;z<2;++z){int er=0,rr=0;for(const auto&a:s.a){if(a.state==2&&a.token==(z?2:0))er=a.radio;if(a.state==2&&a.token==(z?3:1))rr=a.radio;}int q=z?q2:q1,h=z?h2:h1;d[z]=er?(!h?std::min(q,er):(rr?std::min({q,er,rr}):0)):0;}return d;}
void gtick(GS&s,int q1,int q2,int h1,int h2,bool accumulate,GEpisodeOutput*out=nullptr){auto d=gdelivery(s,q1,q2,h1,h2);if(accumulate){int f=s.failed_zone-1,i=1-f;s.at+=d[0]+d[1];s.dt+=q1+q2;s.ai+=d[i];s.di+=i?q2:q1;s.zd[0]+=q1;s.zd[1]+=q2;s.za[0]+=d[0];s.za[1]+=d[1];if(s.post_time<60){s.af+=d[f];s.df+=f?q2:q1;}}
    for(auto&a:s.a){if(a.edge_remaining){a.energy-=a.fast?6:5;if(--a.edge_remaining==0){a.node=a.edge_to;gcontinue(a);if(out)out->event_count++;}}else if(a.token<0&&a.node==0)a.energy=std::min(800,a.energy+10);else if(a.state==2)a.energy-=(a.token==0||a.token==2)?2:1;else if(a.token>=0&&a.node==gtoken_node(a.token)&&s.clear[a.token]==0&&!(a.token==(s.failed_zone==1?0:2)&&s.post_time>=0&&s.post_time<20)){if(++a.elapsed==gacq(a.token)){a.state=2;if(out)out->event_count++;}}if(a.energy<100&&out)out->safety_violation=1;}for(int&t:s.clear)if(t)--t;s.post_time++;}
void gtoken_surfaces(const GS&s,std::array<int,4>&states,std::array<int,4>&elapsed){for(int t=0;t<4;++t){int rank;states[t]=gtoken_state(s,t,elapsed[t],rank);}}
void gobservation(const GS&s,int epoch,int q1,int q2,int h1,int h2,const std::int32_t*presentation,GDecisionTrace&tr){tr={};tr.active_count=(int)s.a.size();tr.epoch=epoch;std::array<int,4>ts{},te{};gtoken_surfaces(s,ts,te);for(int t=0;t<4;++t){tr.token_state[t]=ts[t];tr.token_elapsed[t]=te[t];}
    std::array<bool,9>presented{};int row=0;for(int position=0;position<8&&row<(int)s.a.size();++position){int rank=presentation[position],ai=gfind(s,rank);if(ai<0)continue;if(presented[rank])throw std::logic_error("presentation");presented[rank]=true;const GA&a=s.a[ai];double*r=&tr.agent_rows[row*38];r[a.fast?0:1]=1;r[2]=a.radio/2.0;if(a.edge_remaining){static const int ef[5][5]={{-1,5,-1,9,-1},{6,-1,7,13,-1},{-1,8,-1,-1,-1},{10,14,-1,-1,11},{-1,-1,-1,12,-1}};int ix=ef[a.edge_from][a.edge_to];if(ix<5)throw std::logic_error("edge encoding");r[3+ix]=1;r[18]=a.edge_remaining/40.0;}else r[3+a.node]=1;r[19]=a.energy/800.0;r[20+(a.token<0?4:a.token)]=1;r[25]=a.elapsed/6.0;for(int t=0;t<4;++t){int fixed;bool available=!gfixed_token(s,t,fixed)||fixed==a.rank;auto em=gcontingency(s,a,t);int legal=!genroute(a)&&available&&em.second>=0;tr.legality[row*4+t]=legal;tr.eta[row*4+t]=legal?em.first:0;tr.margin_fifths[row*4+t]=legal?em.second:0;r[26+t]=legal;r[30+t]=legal?em.first/140.0:0;r[34+t]=legal?em.second/700.0:0;}row++;}if(row!=(int)s.a.size())throw std::logic_error("presentation");
    auto d=gdelivery(s,q1,q2,h1,h2);for(int z=0;z<2;++z){double*r=&tr.zone_rows[z*15];int ex=z?2:0,re=ex+1;r[0]=(z?q2:q1)/2.0;r[1+(z?h2:h1)]=1;r[3+ts[ex]]=1;r[6+ts[re]]=1;r[9]=te[ex]/6.0;r[10]=te[re]/6.0;r[11]=d[z]/2.0;r[12]=s.clear[ex]/20.0;r[13]=s.zd[z]/240.0;r[14]=s.za[z]/240.0;}tr.globals[0]=epoch/6.0;tr.globals[1]=std::log1p((double)s.a.size())/std::log(8.0);tr.globals[2+(s.failed_zone-1)]=1;}
GS gstate_from_episode(const GEpisodeInput&in){GS s;s.failed_zone=in.failed_zone;s.post_time=-120;for(int i=0;i<in.active_count;++i){const auto&x=in.agents[i];s.a.push_back(GA{x.rank,x.opaque_rank,x.fast,x.radio,x.node,x.edge_from,x.edge_to,x.edge_remaining,x.destination_node,x.token,x.token_state,x.acquisition_elapsed,x.energy_fifths});}return s;}
int grun_episode(const GEpisodeInput&in,GEpisodeOutput&out){if(in.magic!=kMagic||in.abi!=kAbiVersion||in.failed_zone<1||in.failed_zone>2||in.active_count<4||in.active_count>8)return 1;GS s=gstate_from_episode(in);out={};for(int e=0;e<6;++e){GC c=gprehistory(s,in.blocked1[e],in.blocked2[e]);for(int t=0;t<4;++t)out.prehistory_commands[4*e+t]=c.o[t];if(gapply(s,c))return 2;for(int j=0;j<20;++j){gtick(s,in.demand1[e],in.demand2[e],in.blocked1[e],in.blocked2[e],false,&out);out.integrated_ticks++;}out.prehistory_decisions++;}
    int ft=in.failed_zone==1?0:2;for(auto it=s.a.begin();it!=s.a.end();++it)if(it->token==ft&&it->state==2){out.failed_rank=it->rank;s.a.erase(it);break;}if(!out.failed_rank)return 3;s.clear[ft]=20;s.post_time=0;
    for(int e=0;e<6;++e){int q1=in.demand1[e+6],q2=in.demand2[e+6],h1=in.blocked1[e+6],h2=in.blocked2[e+6];gobservation(s,e,q1,q2,h1,h2,&in.post_presentation[e*8],out.traces[e]);GC c;for(int t=0;t<4;++t){c.o[t]=in.post_commands[4*e+t];out.traces[e].command[t]=c.o[t];}int command_error=gapply(s,c);if(command_error)return 100+command_error;for(int j=0;j<20;++j){gtick(s,q1,q2,h1,h2,true,&out);out.integrated_ticks++;}out.post_decisions++;}
    out.fail_delivered=s.af;out.fail_demand=s.df;out.total_delivered=s.at;out.total_demand=s.dt;out.intact_delivered=s.ai;out.intact_demand=s.di;return(out.safety_violation||out.exclusivity_violation)?5:0;}

GS gstate_from_bcrh(const GBcrhInput&in){GS s;s.failed_zone=in.failed_zone;s.post_time=20*in.epoch;s.af=in.accrued_fail_delivered;s.df=in.accrued_fail_demand;s.at=in.accrued_total_delivered;s.dt=in.accrued_total_demand;for(int t=0;t<4;++t)s.clear[t]=in.clearance[t];for(int i=0;i<in.active_count;++i){const auto&x=in.agents[i];s.a.push_back(GA{x.rank,x.opaque_rank,x.fast,x.radio,x.node,x.edge_from,x.edge_to,x.edge_remaining,x.destination_node,x.token,x.token_state,x.acquisition_elapsed,x.energy_fifths});}return s;}
struct GSchedule{int k{};std::array<std::array<std::array<int,16>,6>,2>del{};int events{},records{};};
GSchedule gpersist(const GBcrhInput&in,const GS&initial,const GC&c){GSchedule r;r.k=in.epoch;for(int e=0;e<16;++e){GS s=initial;std::array<bool,4>released{};if(gapply(s,c))throw std::logic_error("candidate apply");for(int epoch=in.epoch;epoch<6;++epoch){if(epoch>in.epoch){GC same=c;for(int t=0;t<4;++t){if(released[t]){same.o[t]=G_NULL;continue;}int rank=same.o[t],ai=gfind(s,rank);if(rank!=G_NULL&&ai>=0&&!genroute(s.a[ai])&&gcontingency(s,s.a[ai],t).second<0){same.o[t]=G_NULL;released[t]=true;}}if(gapply(s,same))throw std::logic_error("persist apply");}int q1,q2,h1,h2;decode_state(e,q1,q2,h1,h2);int sum[2]={0,0};for(int j=0;j<20;++j){auto d=gdelivery(s,q1,q2,h1,h2);sum[0]+=d[0];sum[1]+=d[1];gtick(s,q1,q2,h1,h2,false);}r.del[0][epoch][e]=sum[0];r.del[1][epoch][e]=sum[1];r.records+=2;}r.events=18*(int)initial.a.size();}return r;}
GSchedule gpersist_checker(const GBcrhInput&in,const GS&initial,const GC&candidate){GSchedule out;out.k=in.epoch;for(int exogenous=15;exogenous>=0;--exogenous){GS state=initial;std::array<int,4>live= candidate.o;if(gapply(state,candidate))throw std::logic_error("checker candidate apply");for(int epoch=in.epoch;epoch<6;++epoch){if(epoch!=in.epoch){GC command;for(int token=3;token>=0;--token){command.o[token]=live[token];int ai=gfind(state,live[token]);if(live[token]!=G_NULL&&ai>=0&&!genroute(state.a[ai])&&gcontingency(state,state.a[ai],token).second<0){live[token]=G_NULL;command.o[token]=G_NULL;}}if(gapply(state,command))throw std::logic_error("checker persist apply");}int q1,q2,h1,h2;decode_state(exogenous,q1,q2,h1,h2);std::array<int,2>delivered{};for(int second=19;second>=0;--second){auto now=gdelivery(state,q1,q2,h1,h2);delivered[0]+=now[0];delivered[1]+=now[1];gtick(state,q1,q2,h1,h2,false);}out.del[0][epoch][exogenous]=delivered[0];out.del[1][epoch][exogenous]=delivered[1];out.records+=2;}out.events=18*(int)initial.a.size();}return out;}
struct GW{std::array<std::array<GBig,16>,6>t{},f{};GBig et,ef;std::uint64_t scale=0;};
void gwalk(bool fail,int zone,int H,int depth,int state,int demand,std::uint64_t p,std::array<int,6>&states,int k,int accrued_units,GW&w){if(depth==H-k){constexpr std::uint64_t L=5354228880ULL;int den_units=accrued_units+demand;GBig add=GBig::from(p).mul(L/den_units);if(fail)w.ef.add(add);else w.et.add(add);for(int j=k;j<=H;++j){if(fail)w.f[j][states[j-k]].add(add);else w.t[j][states[j-k]].add(add);}return;}for(int ne=0;ne<16;++ne){states[depth+1]=ne;gwalk(fail,zone,H,depth+1,ne,demand+demand_inc(ne,fail,zone),p*transition_num(state,ne),states,k,accrued_units,w);}}
GW gweights(const GBcrhInput&in){GW w;int start=state_index(in.demand1,in.demand2,in.blocked1,in.blocked2);std::array<int,6>st{};st[0]=start;gwalk(false,in.failed_zone,5,0,start,demand_inc(start,false,in.failed_zone),1,st,in.epoch,(int)(in.accrued_total_demand/20),w);if(in.epoch<=2){gwalk(true,in.failed_zone,2,0,start,demand_inc(start,true,in.failed_zone),1,st,in.epoch,(int)(in.accrued_fail_demand/20),w);w.scale=15625000000ULL;}return w;}
struct GScore{int fn=0,fd=1;GBig obj;int releases=0;std::array<int,4>serial{};};
std::pair<int,int> gfloor(const GBcrhInput&in,const GSchedule&s){if(in.epoch>2)return{0,1};int bestn=2,bestd=1,cq=in.failed_zone==1?in.demand1:in.demand2,ch=in.failed_zone==1?in.blocked1:in.blocked2;for(int q1=1;q1<=2;++q1)for(int h1=0;h1<=1;++h1)for(int q2=1;q2<=2;++q2)for(int h2=0;h2<=1;++h2){int n=(int)in.accrued_fail_delivered,d=(int)in.accrued_fail_demand;int e0=state_index(in.demand1,in.demand2,in.blocked1,in.blocked2),e1=state_index(in.failed_zone==1?q1:in.demand1,in.failed_zone==1?in.demand2:q1,in.failed_zone==1?h1:in.blocked1,in.failed_zone==1?in.blocked2:h1),e2=state_index(in.failed_zone==1?q2:in.demand1,in.failed_zone==1?in.demand2:q2,in.failed_zone==1?h2:in.blocked1,in.failed_zone==1?in.blocked2:h2);int es[3]={e0,e1,e2};for(int j=in.epoch;j<=2;++j){n+=s.del[in.failed_zone-1][j][es[j-in.epoch]];int qq;int a,b,c,dd;decode_state(es[j-in.epoch],a,b,c,dd);qq=in.failed_zone==1?a:b;d+=20*qq;}if((std::int64_t)n*bestd<(std::int64_t)bestn*d){bestn=n;bestd=d;}}int g=std::gcd(bestn,bestd);return{bestn/g,bestd/g};}
GScore gscore(const GBcrhInput&in,const GS&state,const GC&c,const GW&w,bool checker){GSchedule s=gpersist(in,state,c);GBig t=w.et.mul((std::uint64_t)in.accrued_total_delivered),f;if(in.epoch<=2)f=w.ef.mul((std::uint64_t)in.accrued_fail_delivered);for(int j=in.epoch;j<6;++j)for(int e=0;e<16;++e){t.add(w.t[j][e].mul(s.del[0][j][e]+s.del[1][j][e]));if(in.epoch<=2&&j<=2)f.add(w.f[j][e].mul(s.del[in.failed_zone-1][j][e]));}if(in.epoch<=2)t.add(f.mul(w.scale));auto fl=gfloor(in,s);int rel=0;for(const auto&a:state.a)if(a.state==2&&a.token>=0&&c.o[a.token]!=a.rank)rel++;return{fl.first,fl.second,t,rel,gserial(state,c)};}
GScore gscore_checker(const GBcrhInput&in,const GS&state,const GC&c,const GW&w){GSchedule s=gpersist_checker(in,state,c);GBig t=w.et.mul((std::uint64_t)in.accrued_total_delivered),f;if(in.epoch<=2)f=w.ef.mul((std::uint64_t)in.accrued_fail_delivered);for(int e=15;e>=0;--e)for(int j=5;j>=in.epoch;--j){t.add(w.t[j][e].mul(s.del[0][j][e]+s.del[1][j][e]));if(in.epoch<=2&&j<=2)f.add(w.f[j][e].mul(s.del[in.failed_zone-1][j][e]));}if(in.epoch<=2)t.add(f.mul(w.scale));auto fl=gfloor(in,s);int rel=0;for(auto it=state.a.rbegin();it!=state.a.rend();++it)if(it->state==2&&it->token>=0&&c.o[it->token]!=it->rank)rel++;return{fl.first,fl.second,t,rel,gserial(state,c)};}
bool gbetter(const GScore&a,const GScore&b){std::int64_t l=(std::int64_t)a.fn*b.fd,r=(std::int64_t)b.fn*a.fd;if(l!=r)return l>r;if(a.obj!=b.obj)return a.obj>b.obj;if(a.releases!=b.releases)return a.releases<b.releases;return a.serial<b.serial;}
std::uint64_t gdigest(const std::vector<GC>&all,const std::vector<GScore>&scores){std::uint64_t h=1469598103934665603ULL;for(std::size_t i=0;i<all.size();++i){for(int x:all[i].o){h^=(std::uint64_t)(x+1);h*=1099511628211ULL;}h^=scores[i].fn;h*=1099511628211ULL;h^=scores[i].fd;h*=1099511628211ULL;for(auto x:scores[i].obj.x){h^=x;h*=1099511628211ULL;}}return h;}
#include "bpcr_checker.hpp"
int grun_bcrh(const GBcrhInput&in,GBcrhOutput&out){
    constexpr std::size_t candidate_cap=1961;
    if(in.magic!=kMagic||in.abi!=kAbiVersion||in.epoch<0||in.epoch>5||in.failed_zone<1||in.failed_zone>2||in.active_count<1||in.active_count>7)return 1;
    GS state=gstate_from_bcrh(in);auto scorer_commands=genum(state);std::sort(scorer_commands.begin(),scorer_commands.end(),[](auto&a,auto&b){return a.o<b.o;});
    auto checker_state=independent_checker::build(in);auto checker_commands=independent_checker::enumerate(checker_state);
    if(scorer_commands.empty()||scorer_commands.size()>candidate_cap||checker_commands.size()>candidate_cap||scorer_commands.size()!=checker_commands.size())return 2;
    for(std::size_t i=0;i<scorer_commands.size();++i)if(scorer_commands[i].o!=checker_commands[i].o)return 2;
    GW weights=gweights(in);std::vector<GScore>scorer_scores;for(const auto&c:scorer_commands)scorer_scores.push_back(gscore(in,state,c,weights,false));std::size_t scorer_selected=0;for(std::size_t i=1;i<scorer_commands.size();++i)if(gbetter(scorer_scores[i],scorer_scores[scorer_selected]))scorer_selected=i;
    auto checker=independent_checker::evaluate(in);if(checker.records.size()!=scorer_commands.size())return 2;out={};out.candidate_count=(int)scorer_commands.size();out.independent_enumerator_equal=1;
    if(!out.independent_enumerator_equal||checker.records.empty())return 2;const auto&checked_selected=checker.records[checker.selected];for(int t=0;t<4;++t){out.scorer_command[t]=scorer_commands[scorer_selected].o[t];out.checker_command[t]=checked_selected.command.o[t];}out.scorer_checker_equal=scorer_commands[scorer_selected].o==checked_selected.command.o&&scorer_scores[scorer_selected].fn==checked_selected.score.fn&&scorer_scores[scorer_selected].fd==checked_selected.score.fd&&scorer_scores[scorer_selected].obj.x==checked_selected.score.objective.x;out.post60_reduced=in.epoch>=3;out.floor_num=scorer_scores[scorer_selected].fn;out.floor_den=scorer_scores[scorer_selected].fd;out.releases=scorer_scores[scorer_selected].releases;out.event_records=18*in.active_count;out.reward_records=288;for(int i=0;i<4;++i){out.objective_limbs[i]=scorer_scores[scorer_selected].obj.x[i];out.checker_objective_limbs[i]=checked_selected.score.objective.x[i];}out.candidate_digest=gdigest(scorer_commands,scorer_scores);out.checker_digest=checker.digest;
    for(std::size_t i=0;i<scorer_commands.size();++i){auto&r=out.records[i];const auto&checked=checker.records[i];for(int t=0;t<4;++t)r.command[t]=scorer_commands[i].o[t];r.floor_num=scorer_scores[i].fn;r.floor_den=scorer_scores[i].fd;r.releases=scorer_scores[i].releases;r.checker_floor_num=checked.score.fn;r.checker_floor_den=checked.score.fd;r.checker_releases=checked.score.releases;for(int j=0;j<4;++j){r.objective_limbs[j]=scorer_scores[i].obj.x[j];r.checker_objective_limbs[j]=checked.score.objective.x[j];}r.exact_match=scorer_commands[i].o==checked.command.o&&scorer_scores[i].fn==checked.score.fn&&scorer_scores[i].fd==checked.score.fd&&scorer_scores[i].releases==checked.score.releases&&scorer_scores[i].obj.x==checked.score.objective.x;}return 0;
}
int gchecker_detects_perturbation(const GBcrhInput&in){GBcrhOutput out{};int status=grun_bcrh(in,out);if(status||!out.candidate_count)return 0;out.records[0].objective_limbs[0]^=1ULL;return out.records[0].objective_limbs[0]!=out.records[0].checker_objective_limbs[0];}
int gsensitivity_value(const GSensitivityInput&in,const GS&initial,const GC&candidate){GS state=initial;std::array<bool,4>released{};if(gapply(state,candidate))throw std::logic_error("sensitivity candidate");int value=0;for(int epoch=0;epoch<3;++epoch){if(epoch){GC same=candidate;for(int t=0;t<4;++t){if(released[t]){same.o[t]=G_NULL;continue;}int ai=gfind(state,same.o[t]);if(same.o[t]!=G_NULL&&ai>=0&&!genroute(state.a[ai])&&gcontingency(state,state.a[ai],t).second<0){same.o[t]=G_NULL;released[t]=true;}}if(gapply(state,same))throw std::logic_error("sensitivity persist");}for(int second=0;second<20;++second){auto d=gdelivery(state,in.demand1[epoch],in.demand2[epoch],in.blocked1[epoch],in.blocked2[epoch]);value+=d[in.current.failed_zone-1];gtick(state,in.demand1[epoch],in.demand2[epoch],in.blocked1[epoch],in.blocked2[epoch],false);}}return value;}
int grun_sensitivity(const GSensitivityInput&in,GSensitivityOutput&out){if(in.current.epoch!=0||in.current.active_count<1||in.current.active_count>7)return 1;GS state=gstate_from_bcrh(in.current);auto all=genum(state);if(all.empty()||all.size()>1961)return 2;int mini=0,maxi=0,minv=gsensitivity_value(in,state,all[0]),maxv=minv;for(std::size_t i=1;i<all.size();++i){int value=gsensitivity_value(in,state,all[i]);if(value<minv||(value==minv&&all[i].o<all[mini].o)){minv=value;mini=(int)i;}if(value>maxv||(value==maxv&&all[i].o<all[maxi].o)){maxv=value;maxi=(int)i;}}out={};out.candidate_count=(int)all.size();out.min_c60=minv;out.max_c60=maxv;out.sensitive=maxv-minv>=6;for(int t=0;t<4;++t){out.min_command[t]=all[mini].o[t];out.max_command[t]=all[maxi].o[t];}return 0;}

struct GSession{GEpisodeInput input{};GS state{};GEpisodeOutput accounting{};int epoch=0,failed_rank=0;bool terminal=false;};
void ginteractive_snapshot(const GSession&s,GInteractiveOutput&out){
    out.terminal=s.terminal;out.epoch=s.epoch;out.failed_rank=s.failed_rank;out.integrated_ticks=s.accounting.integrated_ticks;out.safety_violation=s.accounting.safety_violation;out.exclusivity_violation=s.accounting.exclusivity_violation;out.event_count=s.accounting.event_count;
    out.fail_delivered=s.state.af;out.fail_demand=s.state.df;out.total_delivered=s.state.at;out.total_demand=s.state.dt;out.intact_delivered=s.state.ai;out.intact_demand=s.state.di;
    for(int i=0;i<24;++i)out.prehistory_commands[i]=s.accounting.prehistory_commands[i];
}
int ginteractive_reset(const GEpisodeInput&in,GSession*&session,GInteractiveOutput&out){
    if(in.magic!=kMagic||in.abi!=kAbiVersion||in.failed_zone<1||in.failed_zone>2||in.active_count<4||in.active_count>8)return 1;
    GSession* p=new GSession();p->input=in;p->state=gstate_from_episode(in);
    for(int e=0;e<6;++e){GC c=gprehistory(p->state,in.blocked1[e],in.blocked2[e]);for(int t=0;t<4;++t)p->accounting.prehistory_commands[4*e+t]=c.o[t];if(gapply(p->state,c)){delete p;return 2;}for(int j=0;j<20;++j){gtick(p->state,in.demand1[e],in.demand2[e],in.blocked1[e],in.blocked2[e],false,&p->accounting);p->accounting.integrated_ticks++;}p->accounting.prehistory_decisions++;}
    int failed_token=in.failed_zone==1?0:2;for(auto it=p->state.a.begin();it!=p->state.a.end();++it)if(it->token==failed_token&&it->state==2){p->failed_rank=it->rank;p->state.a.erase(it);break;}if(!p->failed_rank){delete p;return 3;}p->state.clear[failed_token]=20;p->state.post_time=0;
    out={};ginteractive_snapshot(*p,out);gobservation(p->state,0,in.demand1[6],in.demand2[6],in.blocked1[6],in.blocked2[6],&in.post_presentation[0],out.next_observation);session=p;return 0;
}
int ginteractive_step(GSession&session,const std::int32_t*command,GInteractiveOutput&out){
    if(session.terminal||session.epoch<0||session.epoch>=6)return 1;GC c;for(int t=0;t<4;++t)c.o[t]=command[t];int error=gcommand_error(session.state,c);if(error)return 100+error;
    out={};int e=session.epoch;gobservation(session.state,e,session.input.demand1[e+6],session.input.demand2[e+6],session.input.blocked1[e+6],session.input.blocked2[e+6],&session.input.post_presentation[e*8],out.applied_decision);for(int t=0;t<4;++t)out.applied_decision.command[t]=c.o[t];
    if(gapply(session.state,c))return 2;for(int second=0;second<20;++second){gtick(session.state,session.input.demand1[e+6],session.input.demand2[e+6],session.input.blocked1[e+6],session.input.blocked2[e+6],true,&session.accounting);session.accounting.integrated_ticks++;}session.accounting.post_decisions++;session.epoch++;session.terminal=session.epoch==6;
    ginteractive_snapshot(session,out);if(!session.terminal)gobservation(session.state,session.epoch,session.input.demand1[session.epoch+6],session.input.demand2[session.epoch+6],session.input.blocked1[session.epoch+6],session.input.blocked2[session.epoch+6],&session.input.post_presentation[session.epoch*8],out.next_observation);return(session.accounting.safety_violation||session.accounting.exclusivity_violation)?5:0;
}
int ginteractive_bcrh(const GSession&session,GBcrhOutput&out){if(session.terminal||session.epoch<0||session.epoch>=6)return 1;GBcrhInput in{};in.magic=kMagic;in.abi=kAbiVersion;in.epoch=session.epoch;in.failed_zone=session.state.failed_zone;in.active_count=(int)session.state.a.size();for(int i=0;i<in.active_count;++i){const auto&a=session.state.a[i];in.agents[i]=GAgentIn{a.rank,a.opaque,a.fast,a.radio,a.node,a.edge_from,a.edge_to,a.edge_remaining,a.dest,a.token,a.state,a.elapsed,a.energy};}for(int t=0;t<4;++t)in.clearance[t]=session.state.clear[t];in.accrued_fail_delivered=session.state.af;in.accrued_fail_demand=session.state.df;in.accrued_total_delivered=session.state.at;in.accrued_total_demand=session.state.dt;int e=session.epoch+6;in.demand1=session.input.demand1[e];in.demand2=session.input.demand2[e];in.blocked1=session.input.blocked1[e];in.blocked2=session.input.blocked2[e];return grun_bcrh(in,out);}
int ginteractive_sensitivity(const GSession&session,GSensitivityOutput&out){if(session.terminal||session.epoch!=0)return 1;GSensitivityInput input{};GBcrhOutput unused{};input.current.magic=kMagic;input.current.abi=kAbiVersion;input.current.epoch=0;input.current.failed_zone=session.state.failed_zone;input.current.active_count=(int)session.state.a.size();for(int i=0;i<input.current.active_count;++i){const auto&a=session.state.a[i];input.current.agents[i]=GAgentIn{a.rank,a.opaque,a.fast,a.radio,a.node,a.edge_from,a.edge_to,a.edge_remaining,a.dest,a.token,a.state,a.elapsed,a.energy};}for(int t=0;t<4;++t)input.current.clearance[t]=session.state.clear[t];for(int j=0;j<3;++j){int e=6+j;input.demand1[j]=session.input.demand1[e];input.demand2[j]=session.input.demand2[e];input.blocked1[j]=session.input.blocked1[e];input.blocked2[j]=session.input.blocked2[e];}return grun_sensitivity(input,out);}
int grun_clearance(const GClearanceInput&in,GClearanceOutput&out){if(in.magic!=kMagic||in.abi!=kAbiVersion||(in.holder_state!=1&&in.holder_state!=2))return 1;GS s;s.failed_zone=1;s.post_time=30;s.a.push_back(GA{1,1,0,2,1,-1,-1,0,1,1,in.holder_state,in.holder_state==2?4:2,600});s.a.push_back(GA{2,2,0,2,0,-1,-1,0,0,-1,0,0,800});GC c;c.o={G_NULL,2,G_NULL,G_NULL};int status=gapply(s,c);out={};out.clearance_after_relinquish=s.clear[1];return status;}
int grun_first_prehistory(const GEpisodeInput&in,GPrehistoryOutput&out){if(in.magic!=kMagic||in.abi!=kAbiVersion||in.failed_zone<1||in.failed_zone>2||in.active_count<4||in.active_count>8)return 1;GS s=gstate_from_episode(in);GC command=gprehistory(s,in.blocked1[0],in.blocked2[0]);out={};for(int t=0;t<4;++t)out.command[t]=command.o[t];return 0;}
}

